<tr><td style="border:1px solid #333;padding:8px;text-align:center;">을</td><td style="border:1px solid #333;padding:8px;"></td><td style="border:1px solid #333;padding:8px;text-align:right;">___주</td><td style="border:1px solid #333;padding:8px;text-align:right;">___%</td><td style="border:1px solid #333;padding:8px;"></td></tr>
