  <tr><td style="border:1px solid #333;padding:8px;background:#f1f5f9;font-weight:bold;text-align:center;">중도금2</td><td style="border:1px solid #333;padding:8px;"></td><td style="border:1px solid #333;padding:8px;background:#f1f5f9;font-weight:bold;text-align:center;">공정 __% 시</td><td style="border:1px solid #333;padding:8px;"></td></tr>
