  <tr><td style="border:1px solid #333;padding:8px;">을</td><td style="border:1px solid #333;padding:8px;"></td><td style="border:1px solid #333;padding:8px;">__%</td><td style="border:1px solid #333;padding:8px;">현금/현물</td></tr>
